"use client";

// Illustration (RF-M08-04): requested on demand, shown with its text description (always) and the notice that it is generated by AI.
import { useEffect, useState } from "react";
import { getIllustrationBlob, requestIllustration } from "@/lib/api-client";
import { t } from "@/lib/i18n";

export function IllustrationView({ prompt, alt }: { prompt: string; alt?: string }) {
  const [state, setState] = useState<"loading" | "ok" | "refused" | "limit" | "unavailable">("loading");
  const [src, setSrc] = useState<string | null>(null);
  const [text, setText] = useState(alt ?? prompt);
  useEffect(() => {
    let url: string | null = null;
    let alive = true;
    setState("loading");
    void requestIllustration(prompt, alt)
      .then(async (r) => {
        if (!alive) return;
        if (r.status !== "ok") return setState(r.status);
        setText(r.alt);
        url = URL.createObjectURL(await getIllustrationBlob(r.hash));
        if (alive) { setSrc(url); setState("ok"); }
      })
      .catch(() => alive && setState("unavailable"));
    return () => { alive = false; if (url) URL.revokeObjectURL(url); };
  }, [prompt, alt]);
  return (
    <figure className="flex flex-col gap-2" aria-label={text}>
      {state === "loading" && <p role="status" className="text-muted">{t("illustration.loading")}</p>}
      {/* eslint-disable-next-line @next/next/no-img-element -- a private blob URL: next/image cannot optimize it */}
      {state === "ok" && src && <img src={src} alt={text} className="w-full rounded-control border border-line" />}
      {state !== "loading" && state !== "ok" && <p role="alert" className="text-muted">{t(`illustration.${state}` as "illustration.refused")}</p>}
      <figcaption className="text-sm">{text}<span className="block text-xs text-muted">{t("illustration.caption")}</span></figcaption>
    </figure>
  );
}
